from pathlib import Path
import base64,hashlib,subprocess,zlib

path=Path("lib/main.dart")
expected_pre="acde7038629db5b1431588ef27acf99db63172c502f8828171adb5e55db37fa6"
expected_post="e139574f286ca8443016cef0c5cda6d4a6dce066dc5d7017bf143be43b60e052"
actual=hashlib.sha256(path.read_bytes()).hexdigest()
if actual!=expected_pre:
    raise SystemExit(f"v322 baseline mismatch: expected {expected_pre}, got {actual}")
blob=""
patch=zlib.decompress(base64.b64decode(blob))
subprocess.run(["patch","--batch","--forward","--reject-file=-","-p0"],input=patch,check=True)
actual=hashlib.sha256(path.read_bytes()).hexdigest()
if actual!=expected_post:
    raise SystemExit(f"v322 output mismatch: expected {expected_post}, got {actual}")
body=path.read_text(encoding="utf-8")
for needle in [
    "bridgepoint-v322-whole-system-ai",
    "bridgepoint_ai_answer_ui_v322",
    "whole-system • permission-aware",
    "Ask anything BridgePoint knows",
    "BridgePoint AI is checking the live BridgePoint truth",
]:
    if needle not in body: raise SystemExit(f"v322 release marker missing: {needle}")
if ":_callRpc('bridgepoint_ai_answer_v262',{'p_query':q});" in body:
    raise SystemExit("Legacy customer AI RPC remains active")
print("BridgePoint v322 whole-system AI UI applied and verified.")
